#!/usr/bin/env python3
"""Regenerate the portable IEEE CRC-32 slicing-by-8 tables."""
from pathlib import Path


def generate():
    tables = []
    first = []
    for byte in range(256):
        crc = byte
        for _ in range(8):
            crc = (crc >> 1) ^ (0xEDB88320 if crc & 1 else 0)
        first.append(crc)
    tables.append(first)
    for _ in range(7):
        tables.append([(crc >> 8) ^ first[crc & 0xFF] for crc in tables[-1]])
    lines = [
        "/* Generated by tools/gen_crc32_table.py; do not edit by hand.",
        " * Reflected IEEE polynomial 0xEDB88320. Row n advances a byte's",
        " * contribution through n additional zero bytes. */",
        "static const uint32_t crc32_table[8][256] = {",
    ]
    for table in tables:
        lines.append("    {")
        for offset in range(0, 256, 4):
            values = ", ".join(f"0x{value:08X}u" for value in table[offset:offset + 4])
            lines.append(f"        {values},")
        lines.append("    },")
    lines.append("};")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    destination = Path(__file__).resolve().parents[1] / "src" / "crc32_table.h"
    destination.write_text(generate(), encoding="ascii")
